/* ═══ 整体固定背景图 ═══ */
#this-moment-screen {
  background: url("https://771553.xyz/file/studio/hM9u6cpigimIgfsm.png") center/cover no-repeat fixed !important;
}

.tm-bg-image {
  display: none !important;
}

.tm-bg-overlay {
  background: rgba(255, 255, 255, 0.5) !important;
}

