   晨行书简 · 角色气泡
   ═══════════════════════════════════ */

/* 角色气泡和用户气泡都居中全宽 */
.tm-para-char,
.tm-para-user {
  max-width: 100% !important;
  width: 100% !important;
  margin-left: 0 !important;
  margin-right: 0 !important;
  align-self: center !important;
}

/* 父级控制对齐 */
.tm-para {
  display: block !important;
  max-width: 100% !important;
  width: 100% !important;
  overflow: visible !important;
}

/* 滚动区域 */
.tm-story {
  overflow-y: auto !important;
  overflow-x: clip !important;
}

/* --- Header 重置 --- */
.tc-header {
  position: absolute !important;
  inset: 0 !important;
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  pointer-events: none !important;
  z-index: 3 !important;
}
.tc-header-main { position: absolute !important; inset: 0 !important; }
.tc-meta-stats { display: none !important; }
.tc-meta-subtitle { display: none !important; }
.tc-meta-extra-1 { display: none !important; }
.tc-meta-extra-2 { display: none !important; }
.tc-divider { display: none !important; }
.tc-header-deco-top, .tc-header-deco-bottom { display: none !important; }
.tc-avatar-badge { display: none !important; }

/* ═══ 左边部分：白色底片（角色）═══ */
.tm-para-char::after {
  content: '' !important;
  position: absolute !important;
  top: 9px !important;
  left: -1px !important;
  width: 75% !important;
  height: 193px !important;
  background: #FFFFFF !important;
  z-index: 1 !important;
}

/* ═══ 左边部分：背景图位置（角色）═══ */
.tm-para-char::before {
  content: '' !important;
  position: absolute !important;
  top: 17px !important;
  left: -1px !important;
  width: 78% !important;
  height: 176px !important;
  background: url("https://imgbed.heliar.top/i/qQrKPpKydERvFOR-_1790133143098.png") center/cover no-repeat !important;
  z-index: 2 !important;
}

/* ═══ 右边部分：头像区域 ═══ */
/* top：控制整体垂直位置（越大越往下）
   left：控制整体水平位置（越大越往右）*/
.tc-avatar-area {
  position: absolute !important;
  top: 110px !important;
  transform: translateY(-50%) !important;
  left: calc(-1px + 78% - 155px) !important;
  z-index: 5 !important;
}

/* ═══ 右边部分：白色底片 ═══ */
.tc-avatar-area::before {
  content: '' !important;
  position: absolute !important;
  top: -8px !important;
  left: -5px !important;
  width: 320px !important;
  height: calc(100% + 15px) !important;
  background: #FFFFFF !important;
  z-index: 0 !important;
  overflow: visible !important;
}

/* ═══ 右边部分：头像黑色框 ═══ */
.tc-avatar-frame {
  width: 120px !important;
  height: 80px !important;
  border-radius: 0 !important;
  border: none !important;
  background: #111 !important;
  overflow: hidden !important;
  box-shadow: none !important;
  padding: 0 !important;
  position: relative !important;
  z-index: 1 !important;
}

.tc-avatar-img {
  width: 100% !important;
  height: 100% !important;
  border-radius: 0 !important;
  object-fit: cover !important;
}

/* ═══ 右边部分：图片在白色底片右侧 ═══ */
.tc-avatar-area::after {
  content: '' !important;
  position: absolute !important;
  top: 50% !important;
  left: 115px !important;
  transform: translateY(-50%) !important;
  width: 145px !important;
  height: 80px !important;
  background: url('https://771553.xyz/file/studio/r3sEop3vsPFFmVKR.png') center/contain no-repeat !important;
  z-index: 1 !important;
  pointer-events: none !important;
}

/* ═══ 角色名竖排最左侧 ═══ */
.tc-meta-area {
  position: absolute !important;
  top: 30px !important;
  left: -1px !important;
  z-index: 10 !important;
  transform: none !important;
}

.tc-meta-title {
  writing-mode: vertical-rl !important;
  text-orientation: upright !important;
  font-family: 'ChillKai', serif !important;
  font-size: 18px !important;
  font-weight: normal !important;
  color: #3a2a1a !important;
  letter-spacing: 6px !important;
}

/* ═══ 引用块 ═══ */
.tm-quote-block {
  border-left: 2px solid #ddd !important;
  padding-left: 12px !important;
  color: #4a4a4a !important;
  background: #FFFFFF !important;
  border-radius: 0 4px 4px 0 !important;
}

