/* ═══ 角色气泡容器 ═══ */
/* padding 顺序：上 右 下 左
   上：正文离顶部装饰的距离
   右：正文右边离屏幕边缘的距离
   下：正文底部留白
   左：正文左边离屏幕边缘的距离 */
.tm-para-char {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  padding: 210px 0px 20px 0px !important;
  position: relative !important;
  overflow: visible !important;
  min-height: 210px !important;
}

/* ═══ 用户气泡容器 ═══ */
/* padding 顺序同上 */
.tm-para-user {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  padding: 210px 0px 20px 0px !important;
  position: relative !important;
  overflow: visible !important;
  min-height: 210px !important;
}

